head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70050";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods70050.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_fnSubmit_onclick
 * @description 「연동」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnSubmit_onclick = function(e){
    try {
        scwin.fnSubmit()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70050.btn_fnSubmit_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description 「미연동」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70050.btn_window_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSubmit
 * @description fn Submit 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnSubmit = function () {
    let msg;
    const msg1 = "이 서식은 ";
    const msg2 = "기본정보항목이 자동입력되는 서식입니다.\r\n해당 데이터가 존재하는 경우, 연동하시겠습니까?";
    const msg3 = "";
    const msg4 = " 항목이 자동입력되는 서식입니다.\r\n해당 데이터가 존재하는 경우,\r\n회사선택 팝업을 통하여 연동하시겠습니까?";
    $c.win.closePopup("Y");
    $c.win.closePopup();
};
